INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (1,'Feijoada','https://media.istockphoto.com/id/1355483021/pt/foto/feijoada-typical-brazilian-food-traditional-brazilian-food-made-with-black-beans-top-view-copy.jpg?s=612x612&w=0&k=20&c=u_n8MU0TkaLpRDLBrYVSRGtNGwFJtjjSZ-zKZOyL_Qo=','["1kg de feij\u00e3o preto", "300g de carne seca (dessalgada)", "200g de costelinha de porco", "200g de lombo de porco", "200g de lingui\u00e7a calabresa", "150g de paio", "100g de bacon", "1 cebola grande picada", "4 dentes de alho picados", "2 folhas de louro", "Sal e pimenta-do-reino a gosto"]','["Dessalgar a carne seca: deixe-a de molho por 12 horas, trocando a \u00e1gua v\u00e1rias vezes.", "Corte todas as carnes em peda\u00e7os m\u00e9dios e reserve.", "Fatie a lingui\u00e7a, o paio e o bacon.", "Lave o feij\u00e3o preto e deixe de molho por pelo menos 4 horas.", "Em uma panela grande, coloque o feij\u00e3o com as folhas de louro e \u00e1gua suficiente para cobrir os gr\u00e3os. Cozinhe at\u00e9 que fiquem macios. Reserve.", "Em uma panela separada, cozinhe a carne seca, a costelinha e o lombo at\u00e9 que fiquem macios. Reserve.", "Em uma frigideira, doure o bacon, o paio e a lingui\u00e7a.", "Refogue a cebola e o alho no \u00f3leo ou na gordura do bacon.", "Adicione as carnes j\u00e1 cozidas e refogue por alguns minutos para incorporar os sabores.", "Misture as carnes refogadas ao feij\u00e3o j\u00e1 cozido.", "Deixe cozinhar em fogo baixo por cerca de 30 minutos, mexendo ocasionalmente para engrossar o caldo.", "Ajuste o sal e a pimenta."]',8,'Pessoas','Médio',2,30,'A feijoada é um verdadeiro tesouro da culinária brasileira, símbolo de tradição e sabor. Rica em aromas e texturas, combina a cremosidade do feijão preto com cortes variados de carne, criando um prato robusto e irresistível. Acompanhada de arroz branco, couve refogada, laranja e farofa, a feijoada é um convite ao encontro, à celebração e ao prazer de comer bem.','[1]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (2,'Coxinha','https://i0.statig.com.br/bancodeimagens/22/fi/ci/22fici80lylnpviqgv2zo7f84.jpg','["1 kg de peito de frango desfiado (cozido e temperado)", "2 x\u00edcaras de caldo de frango (do cozimento)", "2 colheres de sopa de manteiga ou margarina", "3 x\u00edcaras de farinha de trigo", "1 colher de ch\u00e1 de sal", "500 g de peito de frango cozido e desfiado", "1 cebola picada", "2 dentes de alho picados", "1 tomate picado", "Sal e pimenta-do-reino a gosto", "Cheiro-verde a gosto", "1/2 x\u00edcara de requeij\u00e3o cremoso ou catupiry (opcional, para um recheio mais cremoso)", "2 ovos batidos", "Farinha de rosca (suficiente para empanar)", "\u00d3leo para fritar"]','["Em uma panela, refogue a cebola e o alho na manteiga ou azeite at\u00e9 dourar.", "Adicione o tomate picado e refogue at\u00e9 que ele se desfa\u00e7a um pouco.", "Acrescente o frango desfiado, as azeitonas e o cheiro-verde. Tempere com sal e pimenta a gosto.", "Se desejar um recheio mais cremoso, adicione o requeij\u00e3o ou catupiry e mexa at\u00e9 incorporar bem. Reserve e deixe esfriar.", "Em uma panela grande, coloque o caldo de frango e a manteiga. Quando ferver, acrescente a farinha de trigo e o sal de uma vez, mexendo sem parar para n\u00e3o empelotar.", "Continue mexendo at\u00e9 que a massa comece a soltar do fundo da panela e fique homog\u00eanea. Deixe esfriar um pouco.", "Com as m\u00e3os, sove a massa at\u00e9 ela ficar lisa e n\u00e3o grudar mais nas m\u00e3os. Se necess\u00e1rio, adicione um pouco mais de farinha at\u00e9 atingir a consist\u00eancia certa.", "Modele pequenas por\u00e7\u00f5es de massa em formato de bolinhas. Com o dedo, fa\u00e7a um buraco no meio e coloque uma colher de sopa de recheio.", "Feche a massa ao redor do recheio e modele a coxinha, fazendo o formato tradicional.", "Passe as coxinhas nos ovos batidos e depois na farinha de rosca, garantindo que fiquem bem empanadas.", "Aque\u00e7a o \u00f3leo em uma panela funda e frite as coxinhas at\u00e9 que fiquem douradas e crocantes.", "Retire-as e coloque em um prato com papel toalha para retirar o excesso de \u00f3leo."]',12,'Pessoas','Médio',1,30,'Essa receita de coxinha é ótima para festas, reuniões e ocasiões especiais. Com a prática, você pode fazer as coxinhas bem rápidas e deliciosas!','[4]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (3,'Paella','https://res.cloudinary.com/worldpackers/image/upload/c_limit,f_auto,q_auto,w_1140/irjevh15v2x1usozninu','["2 x\u00edcaras de arroz (preferencialmente arroz para paella ou arroz de gr\u00e3o curto)", "4 x\u00edcaras de caldo de frango ou peixe", "300 g de camar\u00f5es grandes, limpos e sem casca", "200 g de mexilh\u00f5es ou mariscos", "200 g de lulas cortadas em rodelas", "2 peitos de frango cortados em peda\u00e7os m\u00e9dios", "1 piment\u00e3o vermelho cortado em tiras", "1 tomate grande picado", "1/2 cebola picada", "2 dentes de alho picados", "1/2 x\u00edcara de ervilhas frescas ou congeladas", "1/2 x\u00edcara de vagem cortada", "1 colher de ch\u00e1 de a\u00e7afr\u00e3o ou colorau", "1 colher de ch\u00e1 de pimenta-do-reino", "Sal a gosto", "2 colheres de sopa de azeite de oliva", "1 lim\u00e3o cortado em gomos (para servir)", "Ramos de salsinha para decorar (opcional)"]','["Em uma panela grande, ou paellera (panela pr\u00f3pria para paella), aque\u00e7a o azeite e frite os peda\u00e7os de frango at\u00e9 ficarem dourados. Retire-os da panela e reserve.", "Na mesma panela, adicione o camar\u00e3o e os mexilh\u00f5es, refogando por 2-3 minutos at\u00e9 que fiquem rosados. Retire-os da panela e reserve.", "Na mesma panela, acrescente a cebola, o alho, o piment\u00e3o e o tomate, refogando at\u00e9 que fiquem macios.", "Adicione o arroz e mexa bem para que os gr\u00e3os fiquem envolvidos com o tempero da panela.", "Acrescente o caldo quente, o a\u00e7afr\u00e3o (ou colorau) e misture. Deixe ferver e depois abaixe o fogo.", "Coloque as ervilhas, a vagem, o frango reservado e os frutos do mar (camar\u00f5es, mexilh\u00f5es e lulas). Deixe o arroz cozinhar por cerca de 20 minutos, at\u00e9 o arroz ficar macio e o l\u00edquido ser absorvido", "N\u00e3o mexa no arroz enquanto ele cozinha. Se necess\u00e1rio, adicione mais caldo durante o processo de cozimento.", "Quando o arroz estiver pronto, retire a panela do fogo e cubra com um pano limpo. Deixe descansar por 5 minutos para que os sabores se incorporem.", "Sirva com gomos de lim\u00e3o ao lado e, se desejar, decore com salsinha picada."]',5,'Pessoas','Médio',1,0,'A paella é um prato tradicional da Espanha, originário da região de Valência. Caracteriza-se por uma mistura deliciosa de arroz, legumes, frutos do mar e/ou carnes, tudo cozido junto em uma única panela. O prato é famoso por seus sabores marcantes e pela combinação de ingredientes frescos e variados, como camarões, mariscos, frango, coelho e legumes.','[1]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (4,'Pizza Margherita','https://forbes.com.br/wp-content/uploads/2021/07/Life_Dia-da-Pizza-Veridiana-Margherita_8julho2021_Divulgacao.jpg','["500 g de farinha de trigo", "300 ml de \u00e1gua morna", "10 g de fermento biol\u00f3gico seco", "1 colher de sopa de azeite de oliva", "1 colher de ch\u00e1 de sal", "1 colher de ch\u00e1 de a\u00e7\u00facar", "200 g de molho de tomate (preferencialmente caseiro ou de boa qualidade)", "300 g de mozzarella fresca de b\u00fafala", "Folhas de manjeric\u00e3o fresco a gosto", "Azeite de oliva para regar", "Sal e pimenta-do-reino a gosto"]','["Em uma tigela grande, dissolva o fermento e o a\u00e7\u00facar na \u00e1gua morna. Deixe descansar por 5 minutos at\u00e9 que fique espumoso.", "Adicione a farinha e o sal \u00e0 mistura de fermento, e comece a misturar at\u00e9 formar uma massa. Adicione o azeite e continue amassando at\u00e9 que a massa fique lisa e homog\u00eanea.", "Sove a massa por cerca de 10 minutos. Cubra com um pano \u00famido e deixe crescer por aproximadamente 1 hora, ou at\u00e9 que dobre de tamanho.", "Preaque\u00e7a o forno a 250\u00b0C (ou a temperatura m\u00e1xima do seu forno).", "Quando a massa crescer, divida-a em duas partes, dependendo do tamanho da pizza que voc\u00ea deseja fazer. Abra a massa em uma superf\u00edcie enfarinhada, at\u00e9 formar um disco bem fino.", "Transfira a massa para uma assadeira ou pedra para pizza enfuma\u00e7ada.", "Espalhe uma camada fina de molho de tomate sobre a massa, deixando as bordas livres.", "Coloque a mozzarella de b\u00fafala em fatias finas sobre o molho.", "Tempere com um pouco de sal, pimenta-do-reino e regue com azeite de oliva.", "Asse a pizza no forno preaquecido por 8 a 12 minutos, ou at\u00e9 que a borda esteja dourada e crocante.", "Retire a pizza do forno e adicione as folhas de manjeric\u00e3o fresco por cima.", "Regue com um fio de azeite e sirva imediatamente."]',8,'Fatias','Médio',0,45,'A Pizza Margherita é um clássico da culinária italiana, conhecida por sua simplicidade e sabor incomparável. A combinação de ingredientes frescos e de alta qualidade faz dessa pizza uma das mais queridas no mundo todo.','[2, 1]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (5,'Fondue de Queijo','https://www.receiteria.com.br/wp-content/uploads/fondue-de-queijo-simples-1.jpg','["300 g de queijo Gruy\u00e8re ralado", "300 g de queijo Emmental ralado", "1 dente de alho cortado ao meio", "1 x\u00edcara de vinho branco seco", "1 colher de ch\u00e1 de suco de lim\u00e3o", "1 colher de sopa de amido de milho", "2 colheres de sopa de kirsch (licor de cereja, opcional)", "Pimenta-do-reino e noz-moscada a gosto", "P\u00e3o italiano ou baguete cortados em cubos (para mergulhar)", "Vegetais cozidos (como br\u00f3colis ou cenoura, opcional)", "Carne cozida ou grelhada (opcional)"]','["Comece esfregando o dente de alho cortado ao meio nas laterais da panela de fondue. Isso vai aromatizar o fondue com um leve sabor de alho.", "Em uma tigela, misture os queijos ralados com o amido de milho. Isso ajudar\u00e1 a manter o queijo derretido cremoso e sem separar.", "Aque\u00e7a o vinho branco e o suco de lim\u00e3o em fogo baixo em uma panela ou diretamente na panela de fondue, mexendo para n\u00e3o ferver.", "Quando o vinho estiver quente, adicione aos poucos os queijos, mexendo constantemente at\u00e9 que o queijo derreta completamente e a mistura fique homog\u00eanea.", "Se desejar, adicione o kirsch (licor de cereja) para dar um sabor especial e um toque mais aut\u00eantico. Mexa bem.", "Tempere com pimenta-do-reino e noz-moscada a gosto, ajustando o tempero conforme preferir.", "Se o fondue estiver muito espesso, adicione um pouco mais de vinho ou at\u00e9 mesmo um pouco de \u00e1gua para alcan\u00e7ar a consist\u00eancia desejada.", "Coloque a panela de fondue sobre o queimador de fondue, mantendo o queijo aquecido e derretido.", "Sirva com peda\u00e7os de p\u00e3o italiano ou baguete, legumes cozidos, carnes grelhadas ou at\u00e9 frutas, para serem mergulhados no queijo cremoso."]',5,'Pessoas','Médio',0,20,'Cremoso, aromático e irresistível, o fondue de queijo é a escolha ideal para reunir pessoas queridas ao redor de uma deliciosa experiência compartilhada. Simples de preparar e cheio de sabor, ele transforma qualquer ocasião em um momento inesquecível!','[4, 1]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (6,'Filé Mignon à Parmegiana','https://frigorificoarvoredo.com.br/blog/wp-content/uploads/2023/07/receita-bife-a-parmegiana-.jpg','["4 fil\u00e9s mignon (cerca de 150 a 200 g cada)", "Sal e pimenta-do-reino a gosto", "1 ovo batido", "1 x\u00edcara de farinha de trigo", "1 x\u00edcara de farinha de rosca", "1 colher de sopa de azeite de oliva (para fritar)", "2 x\u00edcaras de molho de tomate caseiro ou pronto", "200 g de queijo mussarela ralado", "50 g de queijo parmes\u00e3o ralado (opcional)", "\u00d3leo para fritar"]','["Tempere os fil\u00e9s mignon com sal e pimenta-do-reino a gosto.", "Passe os fil\u00e9s na farinha de trigo, cobrindo bem ambos os lados. Em seguida, passe no ovo batido e depois na farinha de rosca, pressionando levemente para que a farinha grude bem.", "Aque\u00e7a o \u00f3leo ou azeite em uma frigideira grande e funda em fogo m\u00e9dio-alto.", "Frite os fil\u00e9s empanados por cerca de 3-4 minutos de cada lado, at\u00e9 que fiquem dourados e crocantes. Retire da frigideira e coloque sobre papel toalha para absorver o excesso de gordura.", "Preaque\u00e7a o forno a 180\u00b0C.", "Em uma assadeira, coloque os fil\u00e9s fritos e cubra cada um com o molho de tomate.", "Polvilhe generosamente com o queijo mussarela e, se desejar, adicione o queijo parmes\u00e3o por cima.", "Leve ao forno por cerca de 10-15 minutos ou at\u00e9 que o queijo esteja completamente derretido e dourado.", "Sirva os fil\u00e9s mignon \u00e0 parmegiana acompanhados de arroz branco, batatas fritas ou pur\u00ea de batata."]',4,'Pratos','Médio',0,50,'O Filé Mignon à Parmegiana é uma versão sofisticada do clássico, unindo a maciez do filé empanado ao molho de tomate caseiro e uma camada irresistível de queijo derretido. Ideal para momentos especiais, é uma refeição completa e deliciosa quando acompanhada de arroz branco e batatas fritas.','[1, 3]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (7,'Batida de Vinho','https://vocegastro.com.br/app/uploads/2021/09/como-fazer-batida-de-vinho.jpg','["750 ml de vinho tinto ou branco (escolha um vinho de sua prefer\u00eancia, preferencialmente seco ou meio-seco)", "200 ml de cacha\u00e7a ou vodka", "1/2 x\u00edcara de a\u00e7\u00facar (ajuste conforme o gosto)", "Suco de 2 lim\u00f5es (ou 1 laranja, se preferir)", "Gelo a gosto", "Fatias de lim\u00e3o ou laranja para decorar (opcional)"]','["Preparar os ingredientes: Em um liquidificador, adicione o vinho, a cacha\u00e7a (ou vodka), o a\u00e7\u00facar e o suco de lim\u00e3o. Se quiser uma batida mais doce, pode adicionar um pouco mais de a\u00e7\u00facar.", "Bater a mistura: Bata tudo no liquidificador por cerca de 20 segundos para que os ingredientes fiquem bem misturados e o a\u00e7\u00facar dissolva completamente.", "Adicionar o gelo: Coloque o gelo no liquidificador e bata novamente por mais alguns segundos at\u00e9 que a bebida fique bem gelada e cremosa.", "Sirva a batida de vinho em copos altos, decorados com fatias de lim\u00e3o ou laranja, se desejar."]',5,'Pessoas','Fácil',0,10,'A Batida de Vinho é uma bebida prática, deliciosa e perfeita para momentos de descontração. Feita com vinho tinto, leite condensado e um toque de gelo, ela combina o sabor marcante do vinho com a cremosidade e doçura dos ingredientes. Ideal para reuniões com amigos, festas ou até para saborear em um fim de tarde, essa bebida é simples de preparar e sempre agrada. Sirva bem gelada e aproveite!','[7]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (8,'Palha Italiana','https://www.estadao.com.br/resizer/v2/JDR73DXIZJEB5P6QV2HMKWPKPE.jpg?quality=80&auth=6505661bad79a909da49828f02df308f4fd258d886dedd1f3b3634efd7e0f137&width=1200&height=1200&focal=4378,4755','["1 lata de leite condensado", "2 colheres de sopa de manteiga", "7 colheres de sopa de achocolatado em p\u00f3", "200 g de chocolate meio amargo (ou ao leite, se preferir)", "1 pacote de biscoito de maisena (cerca de 200 g)", "A\u00e7\u00facar de confeiteiro (opcional, para decorar)"]','["Preparando o brigadeiro: Em uma panela m\u00e9dia, adicione o leite condensado, a manteiga e o achocolatado em p\u00f3. Leve ao fogo m\u00e9dio, mexendo constantemente, at\u00e9 que a mistura comece a desgrudar do fundo da panela (ponto de brigadeiro mole).", "Enquanto o brigadeiro est\u00e1 no fogo, derreta o chocolate. Voc\u00ea pode fazer isso no micro-ondas, em intervalos de 30 segundos, mexendo a cada intervalo, ou derreter em banho-maria.", "Quando o brigadeiro estiver pronto, retire do fogo e adicione o chocolate derretido, mexendo bem at\u00e9 que fique homog\u00eaneo.", "Quebre os biscoitos de maisena em peda\u00e7os pequenos. N\u00e3o \u00e9 necess\u00e1rio pic\u00e1-los muito finamente, apenas em peda\u00e7os grandes.", "Montando a palha italiana: Misture os biscoitos quebrados no brigadeiro com chocolate. Mexa bem para que os biscoitos fiquem totalmente cobertos pela mistura de brigadeiro e chocolate.", "Forre uma assadeira pequena com papel manteiga ou untada com manteiga. Coloque a mistura da palha italiana e espalhe uniformemente. Pressione levemente para compactar. Deixe esfriar em temperatura ambiente por algumas horas ou leve \u00e0 geladeira para acelerar o processo.", "Quando estiver bem firme, corte em quadrados e, se desejar, polvilhe com a\u00e7\u00facar de confeiteiro. Sirva e aproveite!"]',12,'Porção','Fácil',3,0,'A Palha Italiana é a combinação perfeita de brigadeiro cremoso com biscoitos crocantes, formando um doce fácil de fazer e irresistível. Com sua textura única e sabor marcante, ela é ideal para lanches, sobremesas ou até para presentear. Simples, prática e deliciosa, essa receita agrada a todos e é perfeita para qualquer ocasião. Experimente e apaixone-se!','[6]',1);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (9,'Caipirinha de morango','https://static.itdg.com.br/images/1200-630/ff1aa29e21777518048d18d63075e9c6/327648-original.jpg','["5 morangos maduros e frescos", "1 lim\u00e3o (opcional, para equilibrar o sabor)", "2 colheres de sopa de a\u00e7\u00facar (ou a gosto)", "50 ml de cacha\u00e7a de boa qualidade", "Gelo a gosto"]','["Prepare os ingredientes: Lave bem os morangos e o lim\u00e3o. Corte os morangos em peda\u00e7os e, se desejar usar o lim\u00e3o, corte-o em fatias ou peda\u00e7os pequenos, removendo as sementes", "Macere as frutas: Em um copo ou recipiente, coloque os morangos (e o lim\u00e3o, se usar) e o a\u00e7\u00facar. Use um socador para macerar as frutas delicadamente, liberando o suco, mas sem amassar demais", "Adicione a cacha\u00e7a: Despeje a cacha\u00e7a sobre a mistura de frutas e mexa bem para misturar os sabores", "Complete com gelo: Encha o copo com gelo. Mexa levemente para resfriar a bebida", "Decore e sirva: Se quiser, decore com um morango inteiro ou uma fatia de lim\u00e3o na borda do copo. Sirva imediatamente e aproveite!"]',1,'Pessoas','Fácil',0,5,'Um Clássico com um Toque de Doçura Surpreenda-se com essa deliciosa variação da tradicional caipirinha brasileira! Feita com morangos frescos e suculentos, essa receita é perfeita para quem busca uma bebida refrescante e cheia de sabor. A doçura natural da fruta se combina perfeitamente com a cachaça, criando um equilíbrio irresistível. Ideal para festas, encontros ou para relaxar no fim do dia, essa caipirinha de morango vai encantar seus convidados.','[7]',2);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (10,'Fricassê de frango','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTAsRG75NOSFMyAhyySdiBqagF2hEVgyCgHng&s','["1 copo de requeij\u00e3o cremoso", "1 lata de creme de leite", "2 peitos de frango desfiados", "100 g de batata palha", "1 pitada de sal", "1 lata de milho verde", "100 g de azeitona sem caro\u00e7o", "200 g de mussarela fatiada", "1 x\u00edcara de \u00e1gua"]','["Bata no liquidificador o milho, o requeij\u00e3o, o creme de leite e a \u00e1gua", "Refogue o creme do liquidificador com o frango desfiado, as azeitonas e o sal at\u00e9 ficar com uma textura espessa", "Coloque o refogado numa assadeira, cubra com mussarela e espalhe a batata palha por cima", "Leve ao forno at\u00e9 borbulhar", "Sirva com arroz branco"]',5,'Porção','Fácil',0,30,'O Fricassé de Frango é uma receita prática e deliciosa que combina frango desfiado, creme de milho cremoso e queijo gratinado. Perfeito para almoços em família ou jantares especiais, é fácil de preparar e agrada a todos. Sirva com arroz branco e salada para uma refeição completa!','[1]',3);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (11,'Cookies de chocolate','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRoYPwI2fNY8Lvbj6hm5R5tfKBAKgdKmNHLkw&s','["2 \u00bd x\u00edcaras de farinha de trigo;", "1 colher de ch\u00e1 de bicarbonato de s\u00f3dio;", "1 colher de ch\u00e1 de sal;", "1 \u00bd tablete de manteiga (amolecida);", "\u00be x\u00edcara de a\u00e7\u00facar granulado;", "2 ovos;", "1 \u00bd colher de ch\u00e1 de extrato de baunilha;", "Gotas ou peda\u00e7os de chocolate"]','["Pr\u00e9-aque\u00e7a o forno a 190\u00b0C (convec\u00e7\u00e3o);", "Misture os ingredientes secos (farinha, bicarbonato e sal) em uma tigela e reserve;", "Em outra tigela, bata a manteiga com o a\u00e7\u00facar granulado e o a\u00e7\u00facar mascavo at\u00e9 obter uma mistura homog\u00eanea;", "Adicione os ovos e o extrato de baunilha \u00e0 mistura de manteiga e misture bem;", "Incorpore os ingredientes secos aos ingredientes \u00famidos e misture at\u00e9 a massa ficar uniforme;", "Adicione as gotas de chocolate e misture;", "Forme cerca de 20 bolinhas e distribua uniformemente em duas assadeiras;", "Asse por 9-12 minutos ou at\u00e9 as bordas ficarem douradas;", "Aproveite!"]',20,'Porção','Fácil',0,40,'Estes Cookies com Gotas de Chocolate são perfeitos para quem ama um biscoito crocante nas bordas e macio por dentro. Feitos com uma massa rica e pedaços generosos de chocolate, eles são ideais para acompanhar o café, adoçar o lanche da tarde ou presentear alguém especial. Além de deliciosos, são fáceis e rápidos de preparar!','[4, 6]',4);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (12,'Bolo de coco gelado','https://static.itdg.com.br/images/1200-630/9fb189fdf20a4fd3dd41913e9a98dc4d/bolo-gelado-de-coco.jpg','["3 ovos (claras separadas);", "2 colheres (sopa) de margarina;", "2 x\u00edcaras de a\u00e7\u00facar;", "1 x\u00edcara de leite;", "2 x\u00edcaras de farinha de trigo;", "1 colher de fermento em p\u00f3;", "1 lata de leite condensado;", "1 vidro de leite de coco (A mesma medida de leite da lata de leite condensado);", "1 pacote de 100 g de coco ralado para polvilhar. (Coloquei coco em flocos)."]','["Bata na batedeira o a\u00e7\u00facar com a margarina;", "Acrescente as gemas peneiradas uma a uma e continue batendo at\u00e9 que se obtenha um creme claro e fofo;", "Em seguida adicione o leite, acrescente a farinha e o fermento peneirados, desligue a batedeira e por \u00faltimo despeje delicadamente as claras em neve;", "Leve para assar em forma untada em forno pr\u00e9 aquecido por aproximadamente 35 minutos;", "Para cobrir o bolo bata os ingredientes (leite condesado e leite de coco)no liquidificador e jogue em cima do bolo ainda quente;", "Polvilhe o coco ralado e leve para gelar por aproximadamente 2 horas."]',20,'Pedaços','Médio',3,0,'O Bolo de Coco Gelado é uma sobremesa clássica, perfeita para os amantes de coco e momentos especiais. Com uma massa fofinha, regada com uma calda cremosa de leite de coco e leite condensado, ele é embrulhado em papel-alumínio para absorver todo o sabor enquanto gela. Cada pedaço é uma explosão de cremosidade e frescor, tornando-o ideal para festas, reuniões ou um lanche irresistível. Experimente e encante-se com essa delícia tropical!','[6]',5);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (13,'Arroz com pequi','https://cdn.deliway.com.br/blog/base/b66/179/80c/arroz-pequi-goias.jpg','["1/4 de x\u00edcara de ch\u00e1 de \u00f3leo ou banha de porco;", "2 dentes de alho espremidos;", "2 x\u00edcaras de ch\u00e1 de arroz;", "Sal a gosto;", "Salsinha, cebolinha picada a gosto;", "1/2 litro de pequi lavado;", "1 cebola grande picada;", "4 x\u00edcaras de ch\u00e1 de \u00e1gua quente;", "Pimenta de cheiro ou malagueta a gosto."]','["Coloque o pequi no \u00f3leo ou gordura fria (se usar o fruto inteiro, n\u00e3o \u00e9 preciso cortar, mas cuidado com o caro\u00e7o);", "Acrescente o alho e a cebola e deixe refogar em fogo baixo, mexendo sempre com uma colher de pau para n\u00e3o grudar na panela, e respingue um pouco de \u00e1gua quando for necess\u00e1rio;", "Quando o pequi j\u00e1 estiver macio e a \u00e1gua secado, acrescente o arroz e deixe fritar um pouco;", "Junte a \u00e1gua e o sal;", "Quando o arroz estiver quase pronto, coloque a pimenta de cheiro ou malagueta a gosto;", "Na hora de servir, polvilhe o arroz com salsa e cebolinha e um pouco de pimenta.\n\n"]',5,'Porção','Médio',0,30,'Esse prato é uma relíquia do estado de Goiás e uma das comidas típicas mais populares da região. O melhor de tudo é que ele é muito fácil de fazer, porque o segredo do sabor está justamente no pequi!','[10, 1]',2);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (14,'Lasanha à bolonhesa','https://static.itdg.com.br/images/640-440/ec2a5e38702c60bf1ace0b5f1c8e9415/shutterstock-739787011.jpg','["500g de carne mo\u00edda", "2 colheres de sopa de \u00f3leo ou azeite", "1 cebola m\u00e9dia picada", "2 dentes de alho picados", "2 latas de molho de tomate (ou 800g)", "Sal e pimenta-do-reino a gosto", "1 colher de ch\u00e1 de a\u00e7\u00facar (opcional, para equilibrar a acidez)", "Cheiro-verde ou manjeric\u00e3o fresco a gosto", "500g de massa para lasanha pr\u00e9-cozida", "300g de queijo mussarela fatiado", "200g de presunto", "50g de queijo parmes\u00e3o ralado"]','["Aque\u00e7a o \u00f3leo ou azeite em uma panela. Refogue a cebola e o alho at\u00e9 dourar.", "Adicione a carne mo\u00edda e cozinhe at\u00e9 dourar.", "Acrescente o molho de tomate, tempere com sal, pimenta e o a\u00e7\u00facar (se necess\u00e1rio).", "Cozinhe em fogo baixo por 20 minutos. Finalize com cheiro-verde ou manjeric\u00e3o.", "Em um refrat\u00e1rio, coloque uma camada fina de molho bolonhesa no fundo.", "Alterne camadas de massa, molho bolonhesa, presunto, mussarela.", "Finalize com molho bolonhesa e polvilhe o queijo parmes\u00e3o ralado.", "Cubra com papel alum\u00ednio e asse em forno pr\u00e9-aquecido a 200\u00b0C por 20 minutos.", "Retire o papel alum\u00ednio e asse por mais 10-15 minutos para dourar."]',6,'Pessoas','Médio',1,0,'A lasanha é um prato clássico da culinária italiana, feito com camadas de massa intercaladas com molho, recheios como carne moída ou vegetais, e finalizado com queijo derretido e dourado. É uma refeição perfeita para momentos especiais ou almoços em família.','[1, 2]',6);
INSERT INTO receitas (id_receita, nome_receita, imagem_receita, ingredientes, passos_receita, num_porcao, tipo_porcao, dificuldade, tempo_hora, tempo_min, `desc`, id_categoria, id_usuario) VALUES (15,'pudim','https://www.minhareceita.com.br/app/uploads/2024/07/mobile-pudim-de-leite.png','["1 x\u00edcara de a\u00e7\u00facar", "1/2 x\u00edcara de \u00e1gua quente", "1 lata de leite condensado (395g)", "2 latas de leite (use a lata de leite condensado como medida)", "3 ovos"]','["Em uma panela, derreta o a\u00e7\u00facar em fogo m\u00e9dio, mexendo sempre, at\u00e9 formar um caramelo dourado.", "Com cuidado, adicione a \u00e1gua quente (pode espirrar!) e mexa at\u00e9 o caramelo dissolver e formar uma calda lisa.", "Despeje a calda em uma forma com furo central (20cm de di\u00e2metro) e espalhe pelo fundo e laterais. Reserve.", "No liquidificador, bata o leite condensado, o leite e os ovos por cerca de 2 minutos, at\u00e9 obter uma mistura homog\u00eanea.", "Despeje a mistura na forma caramelizada.", "Cubra a forma com papel alum\u00ednio.", "Leve ao forno pr\u00e9-aquecido a 180\u00b0C, em banho-maria (coloque a forma dentro de uma assadeira com \u00e1gua quente), por cerca de 1 hora e 30 minutos, ou at\u00e9 o pudim firmar (fa\u00e7a o teste do palito: ele deve sair limpo).", "Deixe o pudim esfriar em temperatura ambiente e, em seguida, leve \u00e0 geladeira por pelo menos 4 horas (Opcioonal)", "Para desenformar, passe uma faca nas bordas e aque\u00e7a levemente o fundo da forma na boca do fog\u00e3o para soltar a calda. Vire sobre um prato e sirva."]',8,'Pessoas','Fácil',2,0,'O pudim é uma das sobremesas mais queridas e simples, caracterizada por sua textura cremosa e cobertura de caramelo. É uma escolha perfeita para encerrar refeições com um toque doce e elegante.','[6]',6);
